ccessible(true); // \u5BF9\u4E8E\u79C1\u6709\u5B57\u6BB5\uFF0C\u9700\u8981\u8FD9\u6837\u505A\n            ageField.set(personObject, 35);\n\n            Method getAgeMethod = personClass.getMethod("getAge");\n            System.out.println("Age: " + getAgeMethod.invoke(personObject));\n\n        } catch (Exception e) {\n            e.printStackTrace();\n        }\n    }\n}\n\nclass Person {\n    private String name;\n    private int age;\n\n    public Person(String name, int age) {\n        this.name = name;\n        this.age = age;\n    }\n\n    public String getName() {\n        return name;\n    }\n\n    public void setName(String name) {\n        this.name = name;\n    }\n\n    public int getAge() {\n        return age;\n    }\n\n    public void setAge(int age) {\n        this.age = age;\n    }\n}\n'})})]})}function h(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},68758(e,n,t){t.d(n,{R:()=>l,x:()=>r});var a=t(2503);let s={},i=a.createContext(s);function l(e){let n=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:l(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);